        if oi >= ct:
            return ('INELIGIBLE', 'CUTOFF_PASSED', '')
    if method == 'DELIVERY':
        if D(stores[store_id]['distance_mi']) > D('10'):
            return ('INELIGIBLE', 'OUT_OF_RADIUS', '')
    # eligible cost
