        rate = D(stores[store_id]['sales_tax_pct'])
    else:
        rate = tax[('Phenix City','AL')]
    taxed = money(price * rate / D('100') + price)
    if method == 'DELIVERY':
        landed = money(taxed + D('9.99'))
    else:
        landed = taxed
    return ('ELIGIBLE', 'NONE', str(landed))

rows = []
eligible = []
for r in offers:
    decision, reason, cost = evaluate(r)
    rows.append((r['offer_id'], decision, reason, cost))
    if decision == 'ELIGIBLE':
        # tie-break: lowest cost, earliest ready, nearest store, lower offer_id
