from datetime import timedelta
eligible.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
chosen = eligible[0] if eligible else None

with open('offer_evaluation.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['offer_id','decision','reason_code','landed_cost_usd'])
    for row in rows:
        w.writerow(row)

res = {
    'eligible_offer_count': len(eligible),
    'chosen_offer_id': chosen[3] if chosen else '',
    'chosen_total_usd': float(chosen[0]) if chosen else 0
}
with open('results.json', 'w') as f:
    json.dump(res, f, indent=2)
    f.write('\n')

print('rows:', len(rows))
print('eligible_count:', len(eligible))
print('chosen:', chosen[3] if chosen else None, chosen[0] if chosen else None)
print('--- evaluation ---')
for row in rows:
    print(row)
print('--- eligible ---')
for e in eligible:
    print(e[3], e[0], e[1], e[2])
